from celery import Celery
app = Celery("llm", broker="redis://localhost:6379/0")

@app.task(bind=True, max_retries=5, rate_limit="60/m")
def summarize_contract_note(self, client_id: str):
    try:
        return llm_summarize(load_contract_note(client_id))
    except RateLimitError as exc:
        raise self.retry(exc=exc, countdown=2 ** self.request.retries)   # backoff

# After market close: push background work to its own queue
for cid in client_ids:
    summarize_contract_note.apply_async(args=[cid], queue="overnight")

# Workers:  celery -A tasks worker -Q overnight --concurrency 8
#           celery -A tasks worker -Q interactive --concurrency 32
